<template>
 <section class="workspace-page gm-operations">
  <header class="gm-page-header">
   <div><div class="gm-eyebrow">Рабочее окружение</div><h1 class="gm-page-title">Контейнеры</h1><p class="gm-page-description">Состояние сервисов, управление и логи — в одном месте.</p></div>
   <div class="operations-header-actions"><span class="operations-refresh">Обновление каждые 5 с</span><b-button variant="outline-primary" :disabled="loading" @click="load">{{ loading?'Обновление…':'Обновить' }}</b-button></div>
  </header>
  <b-alert :show="!!error" variant="danger">{{ error }}</b-alert><b-alert :show="!!notice" variant="success" dismissible @dismissed="notice=''">{{ notice }}</b-alert>
  <div class="container-overview" aria-label="Состояние окружения">
   <button type="button" class="gm-panel overview-card" :class="{selected:state==='all'}" :aria-pressed="String(state==='all')" @click="state='all';tab=0"><span>Всего контейнеров</span><strong>{{ containers.length }}</strong><small>Показать все</small></button>
   <button type="button" class="gm-panel overview-card" :class="{selected:state==='running'}" :aria-pressed="String(state==='running')" @click="state='running';tab=0"><span>Работают</span><strong class="overview-running">{{ containers.filter(c=>c.state==='running').length }}</strong><small>Запущенные сервисы</small></button>
   <div class="gm-panel overview-card"><span>Защищены от управления</span><strong>{{ containers.filter(c=>c.protected).length }}</strong><small>Компоненты gomate</small></div>
  </div>
  <div class="gm-panel operations-workspace">
   <b-tabs v-model="tab">
    <b-tab title="Управление">
     <div class="container-filterbar">
      <b-form-group label="Поиск контейнеров" label-for="containers-search"><b-form-input id="containers-search" v-model="query" placeholder="Имя, образ, ID или порт" aria-label="Поиск контейнеров"/></b-form-group>
      <b-form-group label="Состояние" label-for="containers-state"><b-form-select id="containers-state" v-model="state" :options="states" aria-label="Состояние контейнеров"/></b-form-group>
      <b-button v-if="query||state!=='all'" variant="outline-secondary" @click="query='';state='all'">Сбросить фильтры</b-button>
     </div>
     <div class="container-results-summary"><span>{{ filtered.length }} из {{ containers.length }} контейнеров</span><span>Компоненты gomate доступны только для просмотра</span></div>
     <div class="table-responsive"><table class="table container-table"><thead><tr><th scope="col">Контейнер</th><th scope="col">Состояние</th><th scope="col">Порты</th><th scope="col">Действия</th></tr></thead><tbody><tr v-for="c in pageItems" :key="c.id" :data-container="c.name">
      <td data-label="Контейнер"><div class="container-name"><strong>{{ c.name }}</strong><b-badge v-if="c.protected" variant="secondary">gomate</b-badge></div><div class="container-image">{{ c.image }}</div><code class="container-id">{{ c.id.slice(0,12) }}</code></td>
      <td data-label="Состояние"><b-badge :variant="c.state==='running'?'success':c.state==='paused'?'warning':'secondary'">{{ stateName(c.state) }}</b-badge><div class="container-status">{{ c.status }}</div></td>
      <td data-label="Порты"><div v-for="port in c.ports" :key="port" class="container-port">{{ port }}</div><span v-if="!c.ports.length" class="text-muted">Не опубликованы</span></td>
      <td class="container-actions" data-label="Действия"><div class="container-action-buttons"><b-button size="sm" variant="outline-primary" @click="showLogs(c)">Логи</b-button><template v-if="!c.protected"><b-button v-if="['exited','created'].includes(c.state)" size="sm" variant="outline-success" :disabled="!!busy" @click="act(c,'start')">Запустить</b-button><b-button v-if="c.state==='running'" size="sm" variant="outline-secondary" :disabled="!!busy" @click="act(c,'restart')">Перезапустить</b-button><b-button v-if="c.state==='running'" size="sm" variant="outline-secondary" :disabled="!!busy" @click="act(c,'pause')">Пауза</b-button><b-button v-if="c.state==='paused'" size="sm" variant="outline-success" :disabled="!!busy" @click="act(c,'unpause')">Продолжить</b-button><b-button v-if="['running','paused','restarting'].includes(c.state)" size="sm" variant="outline-danger" :disabled="!!busy" @click="act(c,'stop')">Остановить</b-button></template></div><span v-if="busy===c.id" class="small d-block mt-2" role="status">Выполняется…</span></td>
     </tr></tbody></table></div>
     <div v-if="!filtered.length&&!loading" class="operations-empty"><strong>{{ containers.length?'Ничего не найдено':'Контейнеров пока нет' }}</strong><p>{{ containers.length?'Измените запрос или сбросьте фильтры.':'Запустите Docker-сервисы на хосте — они появятся здесь автоматически.' }}</p><b-button v-if="containers.length" size="sm" variant="outline-primary" @click="query='';state='all'">Показать все контейнеры</b-button></div>
     <div v-if="filtered.length>25" class="container-pagination"><span class="small text-muted">По 25 контейнеров на странице</span><b-pagination v-model="page" :total-rows="filtered.length" :per-page="25" aria-label="Страницы контейнеров"/></div>
    </b-tab>
    <b-tab title="Логи">
     <div class="logs-source-controls">
      <b-form-group label="Контейнер" label-for="logs-container"><b-form-select id="logs-container" v-model="selectedID" :options="[{value:'',text:'Выберите контейнер'},...containers.map(c=>({value:c.id,text:c.name+' · '+stateName(c.state)}))]"/></b-form-group>
      <b-form-group label="Период" label-for="logs-period"><b-form-select id="logs-period" v-model="period" :options="[{value:300,text:'Последние 5 минут'},{value:3600,text:'Последний час'},{value:86400,text:'Последние сутки'},{value:0,text:'Вся доступная история'}]"/></b-form-group>
      <b-form-group label="Последних строк" label-for="logs-tail"><b-form-select id="logs-tail" v-model="tail" :options="[100,500,1000,2000]"/></b-form-group>
      <b-button variant="outline-primary" :disabled="logLoading||!selectedID" @click="fetchLogs">Обновить</b-button>
     </div>
     <div class="logs-filter-controls">
      <b-form-group label="Поиск в логах" label-for="logs-search"><b-form-input id="logs-search" v-model="searchInput" placeholder="Текст в загруженном фрагменте" aria-label="Поиск в логах"/></b-form-group>
      <b-form-group label="Поток" label-for="logs-channel"><b-form-select id="logs-channel" v-model="channel" :options="[{value:'all',text:'stdout + stderr'},{value:'stdout',text:'Только stdout'},{value:'stderr',text:'Только stderr'}]" aria-label="Поток логов" :disabled="snapshot.tty"/></b-form-group>
      <div class="logs-follow-controls"><b-form-checkbox v-model="live" switch>LIVE · 2 с</b-form-checkbox><b-form-checkbox v-model="follow">В конец</b-form-checkbox></div>
     </div>
     <b-alert :show="!!logError" variant="danger">{{ logError }}</b-alert>
     <b-alert :show="snapshot.truncated" variant="warning">Вывод сокращён по лимиту объёма или длины строки. Уменьшите период/число строк. При интенсивном выводе LIVE показывает снимки и может пропускать промежуточные строки.</b-alert>
     <div class="log-viewer-shell">
      <div class="log-viewer-header"><span class="log-viewer-title"><span class="log-indicator" :class="{live:live&&selectedID&&!logError}" aria-hidden="true"/>{{ containers.find(c=>c.id===selectedID)?.name || 'Выберите источник логов' }}</span><span>{{ visibleLogs.length }} из {{ snapshot.lines.length }} строк · {{ fetchedLabel }}</span></div>
      <LogList v-if="selectedID" ref="logs" :items="visibleLogs" @select="openLine"/>
      <div v-if="!selectedID" class="operations-empty logs-empty"><strong>Логи сервиса без переключения окон</strong><p>Выберите контейнер выше или откройте «Логи» в его строке.</p></div>
     </div>
     <p v-if="selectedID&&!visibleLogs.length&&!logLoading" class="text-muted small mt-2">Нет строк для выбранных условий. Измените период или фильтр текста.</p>
     <div class="logs-caption"><span>Поиск действует на загруженный фрагмент. Нажмите строку, чтобы прочитать её целиком.</span><span v-if="snapshot.tty">TTY: stdout и stderr объединены.</span></div>
     <b-modal id="logLine" title="Строка лога" size="lg" ok-only ok-title="Закрыть"><p class="text-muted">{{ selectedLine.time }} · {{ selectedLine.stream }}</p><pre class="full-log">{{ selectedLine.text }}</pre><b-button size="sm" @click="copyLine">Копировать</b-button><span class="ml-2" role="status">{{ copyState }}</span></b-modal>
    </b-tab>
   </b-tabs>
  </div>
 </section>
</template>
<script>
import LogList from '@/components/LogList';
const message=e=>e.response?.data?.error||e.message;
export default {
 components:{LogList},data:()=>({containers:[],loading:false,error:'',notice:'',busy:'',query:'',state:'all',page:1,tab:0,selectedID:'',period:3600,tail:500,searchInput:'',search:'',channel:'all',live:true,follow:true,logLoading:false,logError:'',snapshot:{lines:[],tty:false,truncated:false},selectedLine:{},copyState:'',timer:null,searchTimer:null,listAt:0,logAt:0,controller:null,generation:0,destroyed:false}),
 computed:{states(){return [{value:'all',text:'Все состояния'},...['running','exited','paused','restarting','created','dead'].map(s=>({value:s,text:this.stateName(s)}))]},filtered(){const q=this.query.toLowerCase();return this.containers.filter(c=>(this.state==='all'||c.state===this.state)&&`${c.name} ${c.image} ${c.id} ${c.ports.join(' ')}`.toLowerCase().includes(q))},pageItems(){return this.filtered.slice((this.page-1)*25,this.page*25)},visibleLogs(){const q=this.search.toLowerCase();return this.snapshot.lines.filter(l=>(this.snapshot.tty||this.channel==='all'||l.stream===this.channel)&&l.text.toLowerCase().includes(q))},fetchedLabel(){return this.snapshot.fetchedAt?'Обновлено '+new Date(this.snapshot.fetchedAt).toLocaleTimeString():'Ещё не загружено'}},
 watch:{query(){this.page=1},state(){this.page=1},selectedID:'resetLogs',period:'resetLogs',tail:'resetLogs',tab(v){window.scrollTo(0,0);if(v===1)this.fetchLogs();else{this.controller?.abort();this.generation++;this.logLoading=false}},searchInput(v){clearTimeout(this.searchTimer);this.searchTimer=setTimeout(()=>{this.search=v;this.$refs.logs?.home()},200)},channel(){this.$refs.logs?.home()},live(v){if(v)this.fetchLogs()},follow(v){if(v)this.$nextTick(()=>this.$refs.logs?.bottom())}},
 mounted(){this.load();this.timer=setInterval(this.tick,1000);document.addEventListener('visibilitychange',this.visibility)},beforeDestroy(){this.destroyed=true;clearInterval(this.timer);clearTimeout(this.searchTimer);this.controller?.abort();document.removeEventListener('visibilitychange',this.visibility)},
 methods:{
  stateName(s){return {running:'Работает',exited:'Остановлен',created:'Создан',paused:'На паузе',restarting:'Перезапускается',dead:'Ошибка',removing:'Удаляется'}[s]||s},
  async load(){if(this.loading)return;this.loading=true;try{const {data}=await this.$http.get('/v2/containers');if(this.destroyed)return;this.containers=data;this.error='';this.page=Math.min(this.page,Math.max(1,Math.ceil(this.filtered.length/25)));this.listAt=Date.now()}catch(e){this.error=message(e)}finally{this.loading=false}},
  tick(){if(document.hidden)return;if(Date.now()-this.listAt>=5000)this.load();if(this.tab===1&&this.live&&Date.now()-this.logAt>=2000)this.fetchLogs()},visibility(){if(document.hidden){this.controller?.abort()}else{this.listAt=0;this.logAt=0;this.tick()}},
  async act(c,action){const verb={start:'Запустить',stop:'Остановить',restart:'Перезапустить',pause:'Приостановить',unpause:'Продолжить'}[action];if(['stop','restart','pause'].includes(action)&&!await this.$bvModal.msgBoxConfirm(`${verb} контейнер «${c.name}»? Это прервёт работу сервиса.`,{title:verb+' контейнер',okTitle:verb,cancelTitle:'Отмена',okVariant:'danger'}))return;this.busy=c.id;this.error='';this.notice='';try{await this.$http.post(`/v2/containers/${c.id}/${action}`,{confirm:true});this.notice=`${c.name}: действие выполнено.`;await this.load();if(this.tab===1)this.fetchLogs()}catch(e){await this.load();this.error=message(e)}finally{this.busy=''}},
  showLogs(c){this.selectedID=c.id;this.tab=1;this.$nextTick(this.fetchLogs)},
  resetLogs(){this.generation++;this.controller?.abort();this.controller=null;this.logLoading=false;this.snapshot={lines:[],tty:false,truncated:false};this.channel='all';this.fetchLogs()},
  async fetchLogs(){if(this.destroyed||this.tab!==1||!this.selectedID||this.logLoading||document.hidden)return;this.logLoading=true;const generation=++this.generation;const controller=new AbortController();this.controller=controller;try{const {data}=await this.$http.get(`/v2/containers/${this.selectedID}/logs`,{params:{tail:this.tail,since:this.period?Math.floor(Date.now()/1000)-this.period:0},signal:controller.signal});if(generation!==this.generation||this.destroyed)return;this.snapshot=data;this.logError='';if(this.follow)this.$nextTick(()=>this.$refs.logs?.bottom())}catch(e){if(!controller.signal.aborted&&generation===this.generation)this.logError=message(e)}finally{if(generation===this.generation){this.logLoading=false;this.logAt=Date.now()}}},
  openLine(line){this.selectedLine=line;this.copyState='';this.$bvModal.show('logLine')},
  async copyLine(){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(this.selectedLine.text);else{const el=document.createElement('textarea');el.value=this.selectedLine.text;document.body.appendChild(el);el.select();const ok=document.execCommand('copy');el.remove();if(!ok)throw Error('copy')}this.copyState='Скопировано'}catch{this.copyState='Выделите и скопируйте текст вручную'}},
 }
}
</script>
<style scoped>
.workspace-page{max-width:1600px;margin:auto;padding-bottom:28px}.operations-header-actions,.container-name,.container-results-summary,.container-pagination{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.operations-refresh,.container-results-summary,.container-image,.container-status,.logs-caption{font-size:.8rem;color:var(--gm-muted)}.container-overview{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:0 0 24px}.overview-card{display:flex;flex-direction:column;align-items:flex-start;text-align:left;padding:18px 20px;gap:4px;color:var(--gm-text);background:var(--gm-panel);border:1px solid var(--gm-border);border-radius:var(--gm-radius)}button.overview-card{cursor:pointer}button.overview-card:hover,button.overview-card.selected{border-color:var(--gm-accent);background:var(--gm-accent-soft)}.overview-card span{font-size:.8rem;color:var(--gm-muted)}.overview-card strong{font-size:1.8rem;line-height:1.3;font-variant-numeric:tabular-nums}.overview-card small{color:var(--gm-muted);font-size:.75rem}.overview-running{color:var(--gm-success)}.operations-workspace{padding:20px}.container-filterbar{display:grid;grid-template-columns:minmax(220px,1fr) minmax(190px,260px) auto;align-items:end;gap:16px;margin:20px 0 14px}.container-filterbar .form-group{margin:0}.container-results-summary{justify-content:space-between;padding:0 0 14px}.container-table{margin-bottom:0}.container-table td{vertical-align:middle;overflow-wrap:anywhere;padding:18px 12px}.container-name strong{font-size:.9rem}.container-image{margin:4px 0;max-width:340px;overflow-wrap:anywhere}.container-id,.container-port{font-family:var(--gm-mono);font-size:.75rem;color:var(--gm-muted)}.container-status{margin-top:6px}.container-actions{min-width:200px;max-width:280px}.container-action-buttons{display:flex;gap:6px;flex-wrap:wrap}.container-action-buttons .btn{font-size:.75rem}.container-pagination{justify-content:space-between;padding-top:20px}.container-pagination .pagination{margin:0}.operations-empty{text-align:center;display:flex;flex-direction:column;align-items:center;gap:8px;padding:48px 20px;color:var(--gm-muted)}.operations-empty strong{color:var(--gm-text);font-size:1rem}.operations-empty p{margin:0;max-width:460px;font-size:.85rem}.logs-source-controls{display:grid;grid-template-columns:minmax(200px,2fr) minmax(170px,1fr) 130px auto;gap:16px;align-items:end;margin-top:20px}.logs-source-controls .form-group{margin-bottom:0}.logs-filter-controls{display:grid;grid-template-columns:minmax(200px,2fr) minmax(170px,1fr) auto;gap:16px;align-items:end;margin:16px 0}.logs-filter-controls .form-group{margin:0}.logs-follow-controls{display:flex;flex-wrap:wrap;align-items:center;gap:12px;padding-bottom:8px}.log-viewer-shell{border:1px solid var(--gm-border);border-radius:var(--gm-radius);overflow:hidden;background:var(--gm-panel-alt)}.log-viewer-header{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;padding:12px 16px;font-size:.75rem;border-bottom:1px solid var(--gm-border);color:var(--gm-muted)}.log-viewer-title{display:flex;align-items:center;gap:8px;color:var(--gm-text);font-family:var(--gm-mono);overflow-wrap:anywhere;min-width:0}.log-indicator{height:7px;width:7px;flex-shrink:0;border-radius:50%;background:var(--gm-muted)}.log-indicator.live{background:var(--gm-success)}.logs-caption{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-top:12px}.logs-empty{min-height:260px;justify-content:center}.full-log{white-space:pre-wrap;overflow-wrap:anywhere;max-height:60vh;overflow:auto;font-family:var(--gm-mono);padding:16px;border-radius:var(--gm-radius);background:var(--gm-panel-alt);color:var(--gm-text)}
@media(max-width:900px){.logs-source-controls,.logs-filter-controls{grid-template-columns:1fr 1fr}.logs-source-controls .btn{align-self:end}.container-overview{gap:8px}.overview-card{padding:14px}.overview-card small{display:none}.container-filterbar{grid-template-columns:1fr 1fr}.container-filterbar>.btn{justify-self:start}}
@media(max-width:600px){.operations-workspace{padding:12px}.container-overview{grid-template-columns:1fr 1fr}.container-overview>.overview-card:last-child{grid-column:1/-1;flex-direction:row;align-items:center;justify-content:space-between}.container-overview>.overview-card:last-child strong{font-size:1.1rem}.container-filterbar,.logs-source-controls,.logs-filter-controls{grid-template-columns:1fr}.container-table thead{display:none}.container-table tbody{display:block}.container-table tr{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:18px 0;border-bottom:1px solid var(--gm-border)}.container-table td{padding:0;border:0;min-width:0}.container-table td:first-child,.container-table td:last-child{grid-column:1/-1}.container-table td:not(:first-child):before{content:attr(data-label);display:block;font-size:.7rem;color:var(--gm-muted);margin-bottom:6px}.container-actions{max-width:none;min-width:0}.operations-refresh{display:none}.container-results-summary{align-items:flex-start;gap:4px}.logs-follow-controls{padding:0}.log-viewer-header{padding:12px;gap:6px}}
.container-overview>.gm-panel{margin:0}
</style>
